func processConstants(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := []*object.EmeraldValue{
		{Type: object.ValueSymbol, Data: "WNOHANG", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "WUNTRACED", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "PRIO_PROCESS", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "PRIO_PGRP", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "PRIO_USER", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "RLIM_INFINITY", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "RLIM_SAVED_MAX", Class: R.Classes["Symbol"]},
		{Type: object.ValueSymbol, Data: "RLIM_SAVED_CUR", Class: R.Classes["Symbol"]},
	}
	for _, name := range processRlimitNames {
		values = append(values, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func processConstGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("wrong number of arguments")
	}
	name := specName(args[0])
	if name == "" {
		return typeError("no implicit conversion to String")
	}
	if value, ok := processNamedConstant(name); ok {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: value, Class: R.Classes["Integer"]}
	}
	return argumentError("uninitialized constant Process::" + name)
}

func processConstDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.FalseVal
	}
	if _, ok := processNamedConstant(specName(args[0])); ok {
		return R.TrueVal
	}
	return R.FalseVal
}

func processGetrlimit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("wrong number of arguments")
	}
	resource, ok, err := processRlimitResource(args[0])
	if err != nil {
		return err
	}
	if !ok {
		return argumentError("invalid resource")
	}
	limits, ok := processRlimits[resource]
	if !ok {
		limits = [2]int64{1024, 1024}
		processRlimits[resource] = limits
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{
		{Type: object.ValueInteger, Data: limits[0], Class: R.Classes["Integer"]},
		{Type: object.ValueInteger, Data: limits[1], Class: R.Classes["Integer"]},
	}, Class: R.Classes["Array"]}
}

func processSetrlimit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return argumentError("wrong number of arguments")
	}
	resource, ok, err := processRlimitResource(args[0])
	if err != nil {
		return err
	}
	if !ok {
		return argumentError("invalid resource")
	}
	soft, ok := valueToInteger(args[1])
	if !ok {
		return typeError("no implicit conversion to Integer")
	}
	hard := soft
	if len(args) > 2 {
		var hardOK bool
		hard, hardOK = valueToInteger(args[2])
		if !hardOK {
			return typeError("no implicit conversion to Integer")
		}
	}
	processRlimits[resource] = [2]int64{soft, hard}
	return R.NilVal
}

func processRlimitResource(value *object.EmeraldValue) (int64, bool, *object.EmeraldValue) {
	if value == nil {
		return 0, false, nil
	}
	if value.Type == object.ValueString || value.Type == object.ValueSymbol {
		resource, ok := processRlimitByName(specName(value))
		return resource, ok, nil
	}
	if CallMethod != nil && value.Class != nil {
		if _, ok := value.Class.GetMethod("to_str"); ok {
			coerced := CallMethod(value, "to_str")
			if coerced != nil && coerced.Type == object.ValueString {
				resource, found := processRlimitByName(specName(coerced))
				return resource, found, nil
			}
		}
	}
	if resource, ok := valueToInteger(value); ok {
		return resource, true, nil
	}
	return 0, false, typeError("no implicit conversion to Integer")
}

func processRlimitByName(name string) (int64, bool) {
	if name == "" {
		return 0, false
	}
	if !strings.HasPrefix(name, "RLIMIT_") {
		name = "RLIMIT_" + name
	}
	value, ok := processRlimitValues[name]
	return value, ok
}

func processNamedConstant(name string) (int64, bool) {
	switch name {
	case "WNOHANG":
		return 1, true
	case "WUNTRACED":
		return 2, true
	case "PRIO_PROCESS":
		return 0, true
	case "PRIO_PGRP":
		return 1, true
	case "PRIO_USER":
		return 2, true
	case "RLIM_INFINITY", "RLIM_SAVED_MAX", "RLIM_SAVED_CUR":
		return 1<<63 - 1, true
	}
	if value, ok := processRlimitValues[name]; ok {
		return value, true
	}
	return 0, false
}

func threadLocalKey(value *object.EmeraldValue) (string, bool) {
	if value == nil {
		return "", false
	}
	switch value.Type {
	case object.ValueString, object.ValueSymbol:
		s, ok := value.Data.(string)
		return s, ok
	default:
		if CallMethod == nil || value.Class == nil {
			return "", false
		}
		if _, ok := value.Class.GetMethod("to_str"); !ok {
			return "", false
		}
		coerced := CallMethod(value, "to_str")
		if coerced == nil || coerced.Type != object.ValueString {
			return "", false
		}
		s, ok := coerced.Data.(string)
		return s, ok
	}
}

func threadLocalKeyTypeError() *object.EmeraldValue {
	return typeError("Thread local key must be a Symbol or String")
}

func threadJoin(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 && args[0] != nil && args[0].Type != object.ValueNil {
		switch args[0].Type {
		case object.ValueInteger, object.ValueFloat:
			if data := threadValueData(receiver); data != nil && !data.ran {
				return R.NilVal
			}
		default:
			return typeError("no implicit conversion to float from timeout")
		}
	}
	runThread(receiver)
	releaseThreadMutexes(receiver)
	if data := threadValueData(receiver); data != nil && data.exception != nil {
		return data.exception
	}
	return receiver
}

func threadValue(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	runThread(receiver)
	releaseThreadMutexes(receiver)
	if data.exception != nil {
		LastException = data.exception
		return data.exception
	}
	if data.result != nil {
		return data.result
	}
	return R.NilVal
}

func threadPid(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return threadIndex(receiver, &object.EmeraldValue{Type: object.ValueSymbol, Data: "pid", Class: R.Classes["Symbol"]})
}

func threadBacktrace(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver != currentThread {
		if data := threadValueData(receiver); data != nil {
			if data.finished {
				return R.NilVal
			}
			if !data.ran {
				return &object.EmeraldValue{
					Type:  object.ValueArray,
					Data:  []*object.EmeraldValue{},
					Class: R.Classes["Array"],
				}
			}
		}
	}
	frames, nilResult, err := backtraceFramesFromArgs(0, args...)
	if err != nil {
		return err
	}
	if nilResult {
		return R.NilVal
	}
	return backtraceStringsValue(frames)
}

func threadBacktraceLocations(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver != currentThread {
		if data := threadValueData(receiver); data != nil {
			if data.finished {
				return R.NilVal
			}
			if !data.ran {
				return &object.EmeraldValue{
					Type:  object.ValueArray,
					Data:  []*object.EmeraldValue{},
					Class: R.Classes["Array"],
				}
			}
		}
	}
	frames, nilResult, err := backtraceFramesFromArgs(0, args...)
	if err != nil {
		return err
	}
	if nilResult {
		return R.NilVal
	}
	return backtraceLocationsValue(frames)
}

func currentSourcePath() string {
	if CurrentSpecFile != "" {
		return CurrentSpecFile
	}
	return "spec.rb"
}

func currentBacktraceFramesOrEmpty() []object.RBacktraceLocation {
	if CurrentBacktraceFrames == nil {
		return []object.RBacktraceLocation{{Path: currentSourcePath(), Line: 1, Label: "main"}}
	}
	frames := CurrentBacktraceFrames()
	if len(frames) == 0 {
		return []object.RBacktraceLocation{{Path: currentSourcePath(), Line: 1, Label: "main"}}
	}
	result := append([]object.RBacktraceLocation{}, frames...)
	for i := range result {
		if result[i].Path == "" {
			result[i].Path = currentSourcePath()
		}
		if result[i].Line <= 0 {
			result[i].Line = 1
		}
		if result[i].Label == "" {
			result[i].Label = "main"
		}
	}
	return result
}

func backtraceString(frame object.RBacktraceLocation) string {
	return fmt.Sprintf("%s:%d:in '%s'", frame.Path, frame.Line, frame.Label)
}

func backtraceStrings(frames []object.RBacktraceLocation) []string {
	result := make([]string, len(frames))
	for i, frame := range frames {
		result[i] = backtraceString(frame)
	}
	return result
}

func backtraceStringsValue(frames []object.RBacktraceLocation) *object.EmeraldValue {
	result := make([]*object.EmeraldValue, len(frames))
	for i, bt := range frames {
		result[i] = rubyString(backtraceString(bt))
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func backtraceLocationsValue(frames []object.RBacktraceLocation) *object.EmeraldValue {
	result := make([]*object.EmeraldValue, len(frames))
	for i, frame := range frames {
		result[i] = backtraceLocationValue(frame)
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func backtraceLocationValue(frame object.RBacktraceLocation) *object.EmeraldValue {
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  frame,
		Class: R.Classes["Thread::Backtrace::Location"],
	}
}

func backtraceLocationFrame(receiver *object.EmeraldValue) (object.RBacktraceLocation, bool) {
	if receiver == nil || receiver.Type != object.ValueObject {
		return object.RBacktraceLocation{}, false
	}
	if frame, ok := receiver.Data.(object.RBacktraceLocation); ok {
		return frame, true
	}
	if frame, ok := receiver.Data.(*object.RBacktraceLocation); ok && frame != nil {
		return *frame, true
	}
	return object.RBacktraceLocation{}, false
}

func backtraceFramesFromRange(args []object.RBacktraceLocation, r *object.RRange) ([]object.RBacktraceLocation, bool) {
	if len(args) == 0 || r == nil {
		return nil, true
	}
	length := len(args)
	start := int(r.Start)
	end := int(r.End)
	if start < 0 {
		start = length + start
	}
	if end < 0 {
		end = length + end
	}
	if r.Exclusive {
		end--
	}
	if start < 0 {
		start = 0
	}
	if start >= length {
		return nil, true
	}
	if end >= length {
		end = length - 1
	}
	if end < start {
		return nil, true
	}
	return args[start : end+1], false
}

func backtraceFramesFromArgs(defaultOmit int64, args ...*object.EmeraldValue) ([]object.RBacktraceLocation, bool, *object.EmeraldValue) {
	if len(args) > 2 {
		return nil, false, NewArgumentError("wrong number of arguments")
	}
	frames := currentBacktraceFramesOrEmpty()
	if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueRange {
		r, ok := args[0].Data.(*object.RRange)
		if !ok {
			return nil, false, typeError("wrong argument type")
		}
		sliced, nilResult := backtraceFramesFromRange(frames, r)
		if nilResult {
			return nil, true, nil
		}
		return sliced, false, nil
	}

	omit := defaultOmit
	limit := int64(len(frames))
	hasLimit := false

	if len(args) > 0 {
		value, ok := valueToInteger(args[0])
		if !ok {
			return nil, false, argumentError("wrong argument type")
		}
		omit = value
	}
	if omit < 0 || limit < 0 {
		return nil, false, NewArgumentError("negative argument")
	}
	if len(args) == 2 {
		value, ok := valueToInteger(args[1])
		if !ok {
			return nil, false, argumentError("wrong argument type")
		}
		limit = value
		hasLimit = true
		if limit < 0 {
			return nil, false, NewArgumentError("negative array size")
		}
		if limit == 0 {
			return []object.RBacktraceLocation{}, false, nil
		}
	}
	if int64(len(frames)) < omit {
		return nil, true, nil
	}
	if int64(len(frames)) == omit {
		return []object.RBacktraceLocation{}, false, nil
	}
	start := int(omit)
	end := len(frames)
	if hasLimit {
		end = start + int(limit)
	}
	if end > len(frames) {
		end = len(frames)
	}
	if start > end || start < 0 {
		return nil, true, nil
	}
	return frames[start:end], false, nil
}

func threadBacktraceLocationPath(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	return rubyString(frame.Path)
}

func threadBacktraceLocationAbsolutePath(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	path := frame.Path
	if path == "" || strings.HasPrefix(path, "<") {
		return R.NilVal
	}
	if abs, err := filepath.Abs(path); err == nil {
		path = abs
	}
	if resolved, err := filepath.EvalSymlinks(path); err == nil {
		path = resolved
	}
	return rubyString(path)
}

