func encodingIsASCICompatible(name string) bool {
	upper := strings.ToUpper(name)
	switch upper {
	case "UTF-16BE", "UTF-32", "UTF-32BE":
		return false
	case "UTF-16", "UTF_16", "UTF-16LE", "UTF-32LE":
		return false
	}
	return true
}

