func arrayOne(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	count := 0
	for _, elem := range arr {
		if elem.Type != object.ValueNil && elem.Type != object.ValueBool {
			count++
		}
		if elem.Type == object.ValueBool && elem.Data.(bool) {
			count++
		}
	}
	if count == 1 {
		return R.TrueVal
	}
	return R.FalseVal
}

func arraySum(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError("wrong number of arguments")
	}
	sum := &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	if len(args) == 1 {
		sum = args[0]
	}
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		value := arr[i]
		if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
			value = CallBlock(value)
			if value != nil && value.Type == object.ValueException {
				return value
			}
		}
		if CallMethod == nil {
			return typeError("Array#sum requires +")
		}
		next := CallMethod(sum, "+", value)
		if next == nil || next.Type == object.ValueNil {
			return typeError("Array#sum element cannot be added")
		}
		if next.Type == object.ValueException {
			return next
		}
		sum = next
	}
	return sum
}

func arrayBsearch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return arrayBsearchCommon(receiver, false)
}

func arrayBsearchIndex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return arrayBsearchCommon(receiver, true)
}

func arrayBsearchCommon(receiver *object.EmeraldValue, returnIndex bool) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		values := append([]*object.EmeraldValue(nil), arr...)
		return newGeneratorEnumerator(func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return values, nil
		})
	}
	mode := ""
	for i, elem := range arr {
		result := CallBlock(elem)
		if LastBlockResult != nil {
			breakValue := LastBlockResult
			LastBlockResult = nil
			if breakValue == nil {
				return R.NilVal
			}
			return breakValue
		}
		if result == nil || result.Type == object.ValueNil {
			if mode == "" {
				mode = "boolean"
			}
			continue
		}
		switch result.Type {
		case object.ValueBool:
			if mode == "" {
				mode = "boolean"
			}
			if mode != "boolean" {
				return typeError("wrong argument type")
			}
			if result.Data.(bool) {
				if returnIndex {
					return newInt(int64(i))
				}
				return elem
			}
		case object.ValueInteger:
			if mode == "" {
				mode = "numeric"
			}
			if mode != "numeric" {
				return typeError("wrong argument type")
			}
			n := result.Data.(int64)
			if n == 0 {
				if returnIndex {
					return newInt(int64(i))
				}
				return elem
			}
		case object.ValueFloat:
			if mode == "" {
				mode = "numeric"
			}
			if mode != "numeric" {
				return typeError("wrong argument type")
			}
			n := result.Data.(float64)
			if n == 0 {
				if returnIndex {
					return newInt(int64(i))
				}
				return elem
			}
		default:
			return typeError("wrong argument type")
		}
	}
	return R.NilVal
}

func arrayMax(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return arrayMinMax(receiver, false)
}

func arrayMinMax(receiver *object.EmeraldValue, wantMin bool) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	if len(arr) == 0 {
		return R.NilVal
	}
	best := arr[0]
	for _, elem := range arr[1:] {
		cmp, err := arrayMinMaxCompare(elem, best)
		if err != nil {
			return err
		}
		if (wantMin && cmp < 0) || (!wantMin && cmp > 0) {
			best = elem
		}
	}
	return best
}

func arrayMinMaxCompare(left, right *object.EmeraldValue) (int, *object.EmeraldValue) {
	var cmpValue *object.EmeraldValue
	if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
		cmpValue = CallBlock(left, right)
	} else if CallMethod != nil && left != nil && receiverHasCallableMethod(left, "<=>") {
		cmpValue = CallMethod(left, "<=>", right)
	} else {
		_, ok := rangeCompareValues(left, right)
		if !ok {
			return 0, newRuntimeException(R.Classes["NoMethodError"], "undefined method `<=>'")
		}
	}
	if cmpValue != nil && cmpValue.Type == object.ValueException {
		return 0, cmpValue
	}
	if cmpValue != nil {
		if cmpValue.Type == object.ValueNil {
			return 0, NewArgumentError("comparison of " + left.TypeName() + " with " + right.TypeName() + " failed")
		}
		if cmpValue.Type != object.ValueInteger {
			return 0, typeError("comparison result must be Integer")
		}
		n := cmpValue.Data.(int64)
		if n < 0 {
			return -1, nil
		}
		if n > 0 {
			return 1, nil
		}
		return 0, nil
	}
	cmp, ok := rangeCompareValues(left, right)
	if !ok {
		return 0, NewArgumentError("comparison of " + left.TypeName() + " with " + right.TypeName() + " failed")
	}
	return cmp, nil
}

func arrayMinmax(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	if len(arr) == 0 {
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  []*object.EmeraldValue{R.NilVal, R.NilVal},
			Class: R.Classes["Array"],
		}
	}
	min := arr[0]
	max := arr[0]
	for _, elem := range arr[1:] {
		cmpMin, err := arrayMinMaxCompare(elem, min)
		if err != nil {
			return err
		}
		if cmpMin < 0 {
			min = elem
		}
		cmpMax, err := arrayMinMaxCompare(elem, max)
		if err != nil {
			return err
		}
		if cmpMax > 0 {
			max = elem
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  []*object.EmeraldValue{min, max},
		Class: R.Classes["Array"],
	}
}

func stringGsub(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return receiver
	}
	s := receiver.Data.(string)
	replacement, ok := args[1].Data.(string)
	if !ok {
		replacement = ""
	}
	switch pattern := args[0].Data.(type) {
	case string:
		if pattern == "" {
			return &object.EmeraldValue{Type: object.ValueString, Data: gsubEmptyPattern(s, replacement), Class: R.Classes["String"]}
		}
		result := ""
		for i := 0; i < len(s); {
			idx := strings.Index(s[i:], pattern)
			if idx < 0 {
				result += s[i:]
				break
			}
			result += s[i : i+idx]
			result += replacement
			i += idx + len(pattern)
		}
		return &object.EmeraldValue{Type: object.ValueString, Data: result, Class: R.Classes["String"]}
	case *object.RRegexp:
		if pattern.Pattern == "" {
			return &object.EmeraldValue{Type: object.ValueString, Data: gsubEmptyPattern(s, replacement), Class: R.Classes["String"]}
		}
		expr := "(?m)" + pattern.Pattern
		if strings.Contains(pattern.Options, "i") {
			expr = "(?mi)" + pattern.Pattern
		}
		re, err := regexp.Compile(expr)
		if err != nil {
			return receiver
		}
		result := re.ReplaceAllString(s, replacement)
		return &object.EmeraldValue{Type: object.ValueString, Data: result, Class: R.Classes["String"]}
	}
	return receiver
}

func gsubEmptyPattern(s, replacement string) string {
	var b strings.Builder
	b.WriteString(replacement)
	for _, r := range s {
		b.WriteRune(r)
		b.WriteString(replacement)
	}
	return b.String()
}

func stringSub(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return receiver
	}
	s := receiver.Data.(string)
	replacement, ok := args[1].Data.(string)
	if !ok {
		replacement = ""
	}
	switch pattern := args[0].Data.(type) {
	case string:
		idx := strings.Index(s, pattern)
		if idx < 0 {
			return receiver
		}
		result := s[:idx] + replacement + s[idx+len(pattern):]
		return &object.EmeraldValue{Type: object.ValueString, Data: result, Class: R.Classes["String"]}
	case *object.RRegexp:
		re, err := regexp.Compile(pattern.Pattern)
		if err != nil {
			return receiver
		}
		result := re.ReplaceAllString(s, replacement)
		return &object.EmeraldValue{Type: object.ValueString, Data: result, Class: R.Classes["String"]}
	}
	return receiver
}

func stringSplit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := receiver.Data.(string)
	limit := int64(0)
	hasLimit := false
	if len(args) >= 2 && args[1].Type == object.ValueInteger {
		limit = args[1].Data.(int64)
		hasLimit = true
	}
	if hasLimit && limit == 1 {
		return stringArray([]string{s})
	}

	var parts []string
	trimTrailing := !hasLimit || limit == 0
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		parts = splitWhitespace(s, limit, hasLimit)
		return stringArray(parts)
	}

	switch pattern := args[0].Data.(type) {
	case string:
		parts = splitByStringPattern(s, pattern, limit, hasLimit)
	case *object.RRegexp:
		parts = splitByRegexpPattern(s, pattern, limit, hasLimit)
	default:
		parts = []string{s}
	}
	if trimTrailing {
		parts = trimTrailingEmptyStrings(parts)
	}
	return stringArray(parts)
}

func stringArray(parts []string) *object.EmeraldValue {
	result := make([]*object.EmeraldValue, len(parts))
	for i, p := range parts {
		result[i] = &object.EmeraldValue{
			Type:  object.ValueString,
			Data:  p,
			Class: R.Classes["String"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func splitByStringPattern(s, delim string, limit int64, hasLimit bool) []string {
	if delim == " " {
		return splitWhitespace(s, limit, hasLimit)
	}
	if delim == "" {
		return splitCharacters(s, limit, hasLimit)
	}
	if hasLimit && limit > 0 {
		return strings.SplitN(s, delim, int(limit))
	}
	return strings.Split(s, delim)
}

func splitByRegexpPattern(s string, pattern *object.RRegexp, limit int64, hasLimit bool) []string {
	if pattern.Pattern == "" {
		return splitCharacters(s, limit, hasLimit)
	}
	expr := pattern.Pattern
	if strings.Contains(pattern.Options, "i") {
		expr = "(?i)" + expr
	}
	re, err := regexp.Compile(expr)
	if err != nil {
		return []string{s}
	}
	if hasLimit && limit > 0 {
		return re.Split(s, int(limit))
	}
	return re.Split(s, -1)
}

func splitCharacters(s string, limit int64, hasLimit bool) []string {
	if !hasLimit || limit <= 0 {
		parts := make([]string, 0, len([]rune(s)))
		for _, r := range s {
			parts = append(parts, string(r))
		}
		if hasLimit && limit < 0 {
			parts = append(parts, "")
		}
		return parts
	}
	runes := []rune(s)
	if limit <= 1 || int(limit) >= len(runes)+1 {
		parts := make([]string, 0, len(runes)+1)
		for _, r := range runes {
			parts = append(parts, string(r))
		}
		if int(limit) > len(runes) {
			parts = append(parts, "")
		}
		return parts
	}
	parts := make([]string, 0, limit)
	for i := 0; i < int(limit)-1; i++ {
		parts = append(parts, string(runes[i]))
	}
	parts = append(parts, string(runes[int(limit)-1:]))
	return parts
}

func splitWhitespace(s string, limit int64, hasLimit bool) []string {
	fields := strings.Fields(s)
	if !hasLimit || limit <= 0 || int(limit) >= len(fields) {
		if hasLimit && limit < 0 && strings.TrimSpace(s) != s && len(fields) > 0 {
			return append(fields, "")
		}
		return fields
	}
	if limit == 1 {
		return []string{s}
	}
	parts := make([]string, 0, limit)
	remaining := s
	for len(parts) < int(limit)-1 {
		remaining = strings.TrimLeft(remaining, " \t\n\r\v\f")
		idx := strings.IndexFunc(remaining, func(r rune) bool {
			return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f'
		})
		if idx < 0 {
			return append(parts, remaining)
		}
		parts = append(parts, remaining[:idx])
		remaining = remaining[idx:]
		for len(remaining) > 0 {
			r := rune(remaining[0])
			if r != ' ' && r != '\t' && r != '\n' && r != '\r' && r != '\v' && r != '\f' {
				break
			}
			remaining = remaining[1:]
		}
	}
	parts = append(parts, remaining)
	return parts
}

func trimTrailingEmptyStrings(parts []string) []string {
	for len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	return parts
}

func legacyStringSplit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := receiver.Data.(string)
	delim := ","
	if len(args) > 0 {
		delim = args[0].Data.(string)
	}
	parts := strings.Split(s, delim)
	result := make([]*object.EmeraldValue, len(parts))
	for i, p := range parts {
		result[i] = &object.EmeraldValue{
			Type:  object.ValueString,
			Data:  p,
			Class: R.Classes["String"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

