func fileReadablePredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	path, errVal := pathFromSingleArg(args)
	if errVal != nil {
		return errVal
	}
	info, err := os.Stat(path)
	if err == nil && info.Mode().Perm()&0444 != 0 {
		return R.TrueVal
	}
	return R.FalseVal
}

